{
  "scenario_id": "sc-9db072",
  "overall_assessment": "anomalies",
  "findings": [
    {
      "benefit": "IP",
      "years": [2015, 2024],
      "pattern": "recovery",
      "direction": "increase",
      "magnitude": "Mental Health recovery rate ~2.5x expected, Musculoskeletal ~1.5x expected",
      "confidence": 0.95,
      "evidence": [
        "artifacts/ae_ip_termination.csv shows pooled A/E of 2.492 (z +67.8) for Mental Health and 1.509 (z +24.7) for Musculoskeletal",
        "All other diagnoses cluster near 1.0 (Cancer 0.999, Cardiovascular 1.010, Injury 0.974, Other 0.983)",
        "Yearly IP incidence A/E remains flat (~1.004), confirming the anomaly is driven by termination behavior rather than claim frequency"
      ],
      "recommended_action": "Investigate clinical pathways, policy definitions, and claims handling for Mental Health and Musculoskeletal diagnoses; review and update assumed recovery/termination rates in pricing and reserving models to reflect faster return-to-work; monitor for sustainability."
    }
  ]
}

